UPDATE new_stub ns SET wall_slug = base.slug FROM (
  SELECT ns2.stub_id,
    CASE WHEN EXISTS (
      SELECT 1 FROM public.politician_profiles pp WHERE pp.wall_slug = regexp_replace(regexp_replace(lower(ns2.name || '-' || ns2.role_title), '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g')
    ) THEN regexp_replace(regexp_replace(lower(ns2.name || '-' || ns2.role_title), '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g') || '-' || left(replace(ns2.stub_id::text, '-', ''), 6)
    ELSE regexp_replace(regexp_replace(lower(ns2.name || '-' || ns2.role_title), '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g')
    END AS slug
  FROM new_stub ns2
) base WHERE base.stub_id = ns.stub_id;

INSERT INTO public.profiles (id, role, full_name, onboarding_completed, country, current_ghost_id) SELECT stub_id, 'politician', name, true, 'Canada', gen_random_uuid() FROM new_stub;
INSERT INTO public.politician_profiles (id, political_party_id, wall_slug) SELECT ns.stub_id, pp.id, ns.wall_slug FROM new_stub ns LEFT JOIN public.political_parties pp ON pp.country='Canada' AND lower(pp.name) = lower(ns.party_name);
